SELECT "Index", COUNT(*) AS n_days, MIN(Date) AS min_d, MAX(Date) AS max_d, AVG(High - Low) AS avg_range_abs, AVG((High - Low)/Open) AS avg_range_pct_open, AVG((High - Low)/Close) AS avg_range_pct_close, AVG((High - Low)/((High+Low)/2)) AS avg_range_pct_mid FROM index_trade WHERE Date >= '2020-01-01' AND "Index" IN ('HSI','000001.SS','399001.SZ','N225','NSEI','TWII') GROUP BY "Index" ORDER BY avg_range_pct_close DESC
